head.script:
scwin.screenId = "jldfil35700";

///////// 1. 변수 및 선언 영역 /////////

scwin.subTitle0 = $c.util.getComponent('subTitle0');

scwin.subTitle1 = $c.util.getComponent('subTitle1');

scwin.subTitle2 = $c.util.getComponent('subTitle2');

scwin.divType1 = $c.util.getComponent('divType1');

scwin.nonValue = $c.util.getComponent('nonValue');

scwin.divType2 = $c.util.getComponent('divType2');

scwin.divType3 = $c.util.getComponent('divType3');

scwin.divType8 = $c.util.getComponent('divType8');

scwin.divType10 = $c.util.getComponent('divType10');

scwin.divType6 = $c.util.getComponent('divType6');

scwin.divType7 = $c.util.getComponent('divType7');

scwin.divType9 = $c.util.getComponent('divType9');

scwin.divType4 = $c.util.getComponent('divType4');

scwin.sum2 = $c.util.getComponent('sum2');

scwin.disc1 = $c.util.getComponent('disc1');

scwin.disc2 = $c.util.getComponent('disc2');

scwin.disc3 = $c.util.getComponent('disc3');

scwin.disc4 = $c.util.getComponent('disc4');

scwin.divType5 = $c.util.getComponent('divType5');

scwin.dataArr = null;

scwin.dataArr_trust = null;


///////// 2. 초기화 영역 /////////

// 화면 진입점 — 2구역 최상단 정의, init_* 순차 실행
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 초기화 함수(init_*)를 데이터 의존성 순서로 순차 실행한다.
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.init_recvParam(); // 1) 화면 전환 파라미터 수신
        scwin.init_conds(); // 2) 세션 사용자 유형별 표시 조건 평가
        scwin.init_pageBody(); // 3) 시장구분 초기값 설정 및 초기 화면 구성
    } catch (e) {
        $c.exception.handleError(e, {
            context: 'jldfil35700.onpageload'
        });
    }
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (이름 고정 "paramData"; 실패 표출은 gcc 함수 몫)
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData).
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function() {
    $c.data.recvParamData('dma_pageContext');
};

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
/**
 * @method
 * @name init_conds
 * @description 세션 법인 사용자 유형(corpUsrTpCd)이 11·21인 경우에만 txt_p31 안내 문구를 표시하도록 런타임 조건을 평가한다.
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function() {
    const binds = [{
        id: "txt_p31",
        fn: function() {
            const corpUsrTpCd = $c.data.readSessionValue("corpUsrTpCd", "session.user.corpUsrTpCd");
            return (corpUsrTpCd === '11' || corpUsrTpCd === '21');
        }
    }];
    $c.util.evalConds(binds);
};

/**
 * @method
 * @name init_pageBody
 * @description 시장구분 라디오(rd_mktGubun)를 유가증권(1)로 초기화하고 클릭 핸들러를 호출해 초기 화면을 구성한다.
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function() {
    try {
        $c.util.getComponent("rd_mktGubun").setValue("1");
        (scwin.rd_mktGubun_onclick ? scwin.rd_mktGubun_onclick() : 0);
    } catch (_ex) {
        $c.exception.handleError(_ex, {
            context: 'jldfil35700.onpageload'
        });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name rd_mktGubun_onclick
 * @description 시장구분 라디오(rd_mktGubun) 클릭 시 시장별 기본값·표시 영역을 재구성한다(fn_checkValueMkt 호출).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_mktGubun_onclick = function(e) {
    try {
        const ev = e;
        const event = ev;
        const self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.fn_checkValueMkt()
    } catch (_ex) {
        $c.exception.handleError(_ex, {
            context: 'jldfil35700.rd_mktGubun_onclick'
        });
    }
};

