/**
 * @method
 * @name rate_Stcok
 * @description 유가증권 상장금액 구간별 수수료(상한 8천만원)를 계산한다.
 * @param {Number} i 상장금액(원)
 * @returns {Number|String} 구간별 상장수수료
 * @hidden N
 */
scwin.rate_Stcok = function(i) {
    let rate = "0.0";
    if (i <= 3000000000.0) {
        if (i <= 100000000.0) {
            rate = 250000.0;
        } else {
            if (i > 100000000.0 && i <= 1000000000.0) {
                rate = 500000.0;
            } else {
                rate = (Math.ceil(i / 1000000000.0)) * 500000.0;
            }
        }
    } else {
        if (3000000000.0 < i && i <= 20000000000.0) {
            rate = 1500000.0 + Math.ceil((i - 3000000000.0) / 1000000000.0) * 210000.0;
        } else {
            if (20000000000.0 < i && i <= 50000000000.0) {
                rate = 5070000.0 + Math.ceil((i - 20000000000.0) / 1000000000.0) * 180000.0;
            } else {
                if (50000000000.0 < i && i <= 100000000000.0) {
                    rate = 10470000.0 + Math.ceil((i - 50000000000.0) / 1000000000.0) * 150000.0;
                } else {
                    if (100000000000.0 < i && i <= 200000000000.0) {
                        rate = 17970000.0 + Math.ceil((i - 100000000000.0) / 1000000000.0) * 120000.0;
                    } else {
                        if (200000000000.0 < i && i <= 500000000000.0) {
                            rate = 29970000.0 + Math.ceil((i - 200000000000.0) / 1000000000.0) * 80000.0;
                        } else {
                            if (500000000000.0 < i) {
                                rate = 53970000.0 + Math.ceil((i - 500000000000.0) / 1000000000.0) * 30000.0;
                            }
                        }
                    }
                }
            }
        }
    }
    if (rate > 80000000.0) {
        rate = 80000000.0;
    }
    return rate;
};


