 */
scwin.rate_Stcok_2 = function(i) {
    let rate = "0.0";
    if (i > 0 && i <= 3000000000.0) {
        if (i <= 100000000.0) {
            rate = 250000.0;
        } else {
            if (i > 100000000.0 && i <= 1000000000.0) {
                rate = 500000.0;
            } else {
                rate = (Math.ceil(i / 1000000000.0)) * 500000.0;
            }
        }
    } else {
        if (3000000000.0 < i && i <= 20000000000.0) {
            rate = 1500000.0 + Math.ceil((i - 3000000000.0) / 1000000000.0) * 210000.0;
        } else {
            if (20000000000.0 < i && i <= 50000000000.0) {
                rate = 5070000.0 + Math.ceil((i - 20000000000.0) / 1000000000.0) * 180000.0;
            } else {
                if (50000000000.0 < i && i <= 100000000000.0) {
                    rate = 10470000.0 + Math.ceil((i - 50000000000.0) / 1000000000.0) * 150000.0;
                } else {
                    if (100000000000.0 < i && i <= 200000000000.0) {
                        rate = 17970000.0 + Math.ceil((i - 100000000000.0) / 1000000000.0) * 120000.0;
                    } else {
                        if (200000000000.0 < i && i <= 500000000000.0) {
                            rate = 29970000.0 + Math.ceil((i - 200000000000.0) / 1000000000.0) * 80000.0;
                        } else {
                            if (500000000000.0 < i) {
                                rate = 53970000.0 + Math.ceil((i - 500000000000.0) / 1000000000.0) * 30000.0;
                            }
                        }
                    }
                }
            }
        }
    }
    if (rate > 80000000.0) {
        rate = 80000000.0;
    }
    return rate;
};


/**
 * @method
 * @name rate_Stcok_cos
 * @description 상장금액 구간별 정률(구간 체감 요율) 수수료를 계산한다.
 * @param {Number} i 상장금액(원)
 * @returns {Number|String} 구간별 상장수수료
 * @hidden N
 */
scwin.rate_Stcok_cos = function(i) {
    let rate = "0.0";
    if (i <= 3000000000.0) {
        rate = i * 0.03 / 100;
    } else {
        if (i > 3000000000.0 && i <= 10000000000.0) {
            rate = 900000 + ((i - 3000000000.0) * 0.025 / 100);
        } else {
            if (i > 10000000000.0 && i <= 20000000000.0) {
                rate = 2650000 + ((i - 10000000000.0) * 0.02 / 100);
            } else {
                if (i > 20000000000.0 && i <= 50000000000.0) {
                    rate = 4650000 + ((i - 20000000000.0) * 0.015 / 100);
                } else {
                    if (i > 50000000000.0 && i <= 100000000000.0) {
                        rate = 9150000 + ((i - 50000000000.0) * 0.01 / 100);
                    } else {
                        if (i > 100000000000.0 && i <= 500000000000.0) {
                            rate = 14150000 + ((i - 100000000000.0) * 0.005 / 100);
                        } else {
                            if (i > 500000000000.0 && i <= 1000000000000.0) {
                                rate = 34150000 + ((i - 500000000000.0) * 0.0025 / 100);
                            } else {
                                if (i > 1000000000000.0) {
                                    rate = 46650000 + ((i - 1000000000000.0) * 0.0005 / 100);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    return rate;
};


/**
 * @method
 * @name rate_Bw
 * @description 상장금액 구간별 정액 수수료 테이블로 수수료를 계산한다.
 * @param {Number} i 상장금액(원)
 * @returns {Number} 구간별 정액 수수료
 * @hidden N
 */
scwin.rate_Bw = function(i) {
    let rate = 0.0;
    if (i < 3000000000.0) {
        rate = 0;
    } else {
        if (i >= 3000000000.0 && i < 5000000000.0) {
            rate = 300000;
        } else {
            if (i >= 5000000000.0 && i < 10000000000.0) {
                rate = 700000;
            } else {
                if (i >= 10000000000.0 && i < 15000000000.0) {
                    rate = 1000000;
                } else {
                    if (i >= 15000000000.0 && i < 25000000000.0) {
                        rate = 1200000;
                    } else {
                        if (i >= 25000000000.0 && i < 50000000000.0) {
                            rate = 1300000;
                        } else {
                            if (i >= 50000000000.0 && i < 100000000000.0) {
                                rate = 1400000;
                            } else {
                                if (i >= 100000000000.0 && i < 200000000000.0) {
                                    rate = 1500000;
                                } else {
                                    if (i >= 200000000000.0 && i < 500000000000.0) {
                                        rate = 1600000;
                                    } else {
                                        if (i >= 500000000000.0) {
                                            rate = 1700000;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    return rate;
};


/**
 * @method
 * @name fn_checkValue
 * @description 시장·상장유형·계산구분 선택값을 수집해 히든 필드(ipt_listTp/ipt_kk)에 반영하고 입력 영역 표시·라벨·계산 결과를 재설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.fn_checkValue = function() {
    let mkt = "";
    let mathTp = "올림";
    $c.util.getComponent('dma_goTab1Req').set('bkk', $c.util.getComponent('ipt_kk').getValue());
    mkt = $c.util.getComponent('rd_mktGubun').getValue();
    let listTp = "";
    let kk = "";
    if (mkt === "1") {
        listTp = $c.util.getComponent('rd_listTpGubun0').getValue();
        kk = $c.util.getComponent('rd_gubun').getValue();
    } else {
        if (mkt === "2") {
            listTp = $c.util.getComponent('rd_listTpGubun').getValue();
            kk = $c.util.getComponent('rd_gubun2').getValue();
        } else {
            if (mkt === "3") {
                kk = $c.util.getComponent('rd_gubun3').getValue();
                if (kk === 3) {
                    mathTp = "버림";
                }
                scwin.fn_reset();
            } else {
                if (mkt === "6") {
                    kk = $c.util.getComponent("dma_goTab1Req").get("gubun4");
                } else {
                    if (mkt === "D") {
                        listTp = "";
                        kk = $c.util.getComponent('rd_gubun11').getValue();
                    }
                }
            }
        }
    }
    scwin.changeStockType(mkt, kk);
    scwin.changeType(mkt, kk);
    const cpMathTp = $c.util.getComponent('mathTp');
    (cpMathTp && cpMathTp.setValue) ?
    cpMathTp.setValue(mathTp): ((cpMathTp && cpMathTp.setText) ?
        cpMathTp.setText(mathTp) :
        console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'mathTp'));
    $c.util.getComponent('ipt_listTp').setValue(listTp);
    $c.util.getComponent('ipt_kk').setValue(kk);
    if (mkt === "3" && kk === "1") {
        $c.util.getComponent('txt_tdNm4').setLabel("* 상장할 신탁원본액");
    } else {
        if (mkt === "3" && kk === "2") {
            $c.util.getComponent('txt_tdNm4').setLabel("* 발행원본액");
        } else {
            if (mkt === "3" && kk === "3") {
                $c.util.getComponent('txt_tdNm4').setLabel("* 발행총액");
            }
        }
    }
    $c.util.getComponent("ipt_totListAmt").setValue("");
    $c.util.getComponent("ipt_listCommSum").setValue("");
    $c.util.getComponent("ipt_listCommSumMin").setValue("");
    $c.util.getComponent("ipt_listCommSumAdd").setValue("");
};


/**
 * @method
 * @name fnCheckGubun
 * @description 유가증권 시장에서 액면구분 체크(ipt_checkGubun1) 여부에 따라 액면가/상장금액 입력칸의 읽기전용·배경색을 전환한다.
 * @param {String} mkt 시장구분 코드
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckGubun = function(mkt) {
    const cpCheckGubun1 = $c.util.getComponent('ipt_checkGubun1');
    const gubun1Checked = (!cpCheckGubun1 || typeof cpCheckGubun1.getValue !== 'function') ?
        (console.warn('[sdd] .checked 대상 미해결: ipt_checkGubun1'), false) :
        (cpCheckGubun1.getValue() != null && String(cpCheckGubun1.getValue()) !== '');
    if (mkt === "1" && gubun1Checked === true) {
        for (let x = 1; x < 3; x++) {
            const colName = "n_parval_" + x;
            document.getElementsByName(colName)[0].style.backgroundColor = '#f0f0f0';
            document.getElementsByName(colName)[0].readOnly = true;
            document.getElementsByName(colName)[0].value = "";
            const colName2 = "n_list_amt" + x;
            document.getElementsByName(colName2)[0].readOnly = false;
            document.getElementsByName(colName2)[0].value = "";
        }
    } else {
        if (mkt === "1" && gubun1Checked === false) {
            for (let x = 1; x < 3; x++) {
                const colName = "n_parval_" + x;
                document.getElementsByName(colName)[0].style.backgroundColor = '#ffffff';
                document.getElementsByName(colName)[0].readOnly = false;
                const colName2 = "n_list_amt" + x;
                document.getElementsByName(colName2)[0].readOnly = true;
                document.getElementsByName(colName2)[0].value = "";
            }
        }
    }
};


/**
 * @method
 * @name fn_checkValueMkt
 * @description 시장구분 변경 시 시장별 기본 선택값·라벨·표시 영역을 초기화하고 입력 영역을 재구성한다.
 * @returns {void}
 * @hidden N
 */
scwin.fn_checkValueMkt = function() {
    let mkt = "";
    mkt = $c.util.getComponent('rd_mktGubun').getValue();
    scwin.sum2.setStyle("display", "");
    $c.util.getComponent('txt_feeTotal').setLabel("* 부과 상장수수료");
    scwin.disc4.setStyle("display", 'none');
    scwin.disc3.setStyle("display", 'block');
    $c.util.getComponent('ipt_mkt').setValue(mkt);
    if (mkt === "2") {
        $c.util.getComponent('ipt_listTp').setValue("2");
        $c.util.getComponent("rd_listTpGubun").setValue("2");
        $c.util.getComponent('ipt_kk').setValue("1");
        $c.util.getComponent("rd_gubun2").setValue("1");
        $c.util.getComponent('txt_tdNm1').setLabel("건별 상장주식수");
        $c.util.getComponent('txt_tdNm2').setLabel("* 종가");
        $c.util.getComponent('txt_tdNm3').setLabel("건별 상장할 금액");
        scwin.fn_reset();
        scwin.disc1.setStyle("display", 'block');
        scwin.disc2.setStyle("display", 'none');
    } else {
        if (mkt === "1") {
            $c.util.getComponent('ipt_listTp').setValue("2");
            $c.util.getComponent("rd_listTpGubun0").setValue("2");
            $c.util.getComponent('ipt_kk').setValue("1");
            $c.util.getComponent("rd_gubun").setValue("2");
            $c.util.getComponent('txt_divTp9Nm1').setLabel("건별 상장주식 수");
            $c.util.getComponent('txt_divTp9Nm2').setLabel("* 종가");
            scwin.disc1.setStyle("display", 'none');
            scwin.disc2.setStyle("display", 'block');
            scwin.nonValue.setStyle("display", 'none');
            scwin.fn_reset();
        } else {
            if (mkt === "3") {
                $c.util.getComponent('ipt_kk').setValue("1");
                $c.util.getComponent("rd_gubun3").setValue("1");
                $c.util.getComponent('txt_tdNm4').setLabel("* 상장할 신탁원본액");
                scwin.fn_reset();
            } else {
                if (mkt === "6") {
                    $c.util.getComponent('ipt_kk').setValue("1");
                    $c.util.getComponent("ipt_gubun4").setValue(true);
                    $c.util.getComponent('txt_tdNm1').setLabel("상장주식수");
                    $c.util.getComponent('txt_tdNm2').setLabel("종가");
                    $c.util.getComponent('txt_tdNm3').setLabel("상장금액");
                    scwin.disc1.setStyle("display", 'none');
                    scwin.disc2.setStyle("display", 'none');
                    scwin.fn_reset();
                } else {
                    if (mkt === "D") {
                        $c.util.getComponent('ipt_listTp').setValue("");
                        $c.util.getComponent('ipt_kk').setValue("1");
                        $c.util.getComponent("rd_gubun11").setValue("1");
                        $c.util.getComponent('txt_divTp9Nm1').setLabel("건별 상장증권수");
                        $c.util.getComponent('txt_divTp9Nm2').setLabel("공모가(평가가격)*");
                        scwin.sum2.setStyle("display", "none");
                        $c.util.getComponent('txt_feeTotal').setLabel("부과 상장수수료 합계");
                        scwin.disc1.setStyle("display", 'none');
                        scwin.disc2.setStyle("display", 'none');
                        scwin.disc3.setStyle("display", 'none');
                        scwin.disc4.setStyle("display", 'block');
                        scwin.nonValue.setStyle("display", 'none');
                        scwin.fn_reset();
                    }
                }
            }
        }
    }
    scwin.fnCheckGubun(mkt);
    scwin.changeStockType(mkt, $c.util.getComponent('ipt_kk').getValue());
    scwin.changeType(mkt, $c.util.getComponent('ipt_kk').getValue());
};


/**
 * @method
 * @name fn_rowInput
 * @description 행 반복 입력 컴포넌트를 기본 id와 행 번호로 조회한다(1행=기본 id, n행=기본 id+"_r"+(n-1) — 예: ipt_nStockCount, ipt_nStockCount_r9).
 * @param {String} baseId 1행 컴포넌트 id (예: 'ipt_stockCount')
 * @param {Number} row 행 번호(1~10)
 * @returns {Object} 해당 행의 WebSquare 입력 컴포넌트
 * @hidden N
 */
scwin.fn_rowInput = function(baseId, row) {
    return $c.util.getComponent(row === 1 ? baseId : baseId + '_r' + (row - 1));
};


/**
 * @method
 * @name changeType
 * @description 시장·계산구분에 따라 주권유형 라벨(stock_type·stock_type_r1)과 행별 입력칸(주식수/액면가/상장금액)의 읽기전용·배경색을 전환한다.
 * @param {String} mkt 시장구분 코드
 * @param {String} kk 계산구분 코드
 * @returns {void}
 * @hidden N
 */
scwin.changeType = function(mkt, kk) {
    if (mkt === '1') {
        if (kk === "3") {
            $c.util.getComponent('stock_type').setValue("");
            $c.util.getComponent('stock_type_r1').setValue("");
            for (let i = 3; i < 11; i++) {
                const cpNStockCount = scwin.fn_rowInput('ipt_nStockCount', i);
                const cpNParval = scwin.fn_rowInput('ipt_nParval', i);
                const cpNListAmt = scwin.fn_rowInput('ipt_nListAmt', i);
                cpNStockCount.setReadOnly(false);
                cpNStockCount.setStyle('background-color', '#ffffff');
                cpNParval.setReadOnly(false);
                cpNParval.setStyle('background-color', '#ffffff');
                cpNListAmt.setReadOnly(false);
                cpNListAmt.setStyle('background-color', '#ffffff');
                scwin.fn_reset();
            }
        } else {
            $c.util.getComponent('stock_type').setValue("보통주권");
            $c.util.getComponent('stock_type_r1').setValue("종류주권");
            for (let i = 3; i < 11; i++) {
                const cpNStockCount = scwin.fn_rowInput('ipt_nStockCount', i);
                const cpNParval = scwin.fn_rowInput('ipt_nParval', i);
                const cpNListAmt = scwin.fn_rowInput('ipt_nListAmt', i);
                cpNStockCount.setReadOnly(true);
                cpNStockCount.setStyle('background-color', '#f0f0f0');
                cpNParval.setReadOnly(true);
                cpNParval.setStyle('background-color', '#f0f0f0');
                cpNListAmt.setReadOnly(true);
                cpNListAmt.setStyle('background-color', '#f0f0f0');
                if ($c.util.getComponent('dma_goTab1Req').get('bkk') === "3") {
                    scwin.fn_reset();
                }
            }
        }
    } else {
        if (mkt === '2') {
            for (let i = 2; i < 11; i++) {
                const cpStockCount = scwin.fn_rowInput('ipt_stockCount', i);
                const cpParval = scwin.fn_rowInput('ipt_parval', i);
                const cpListAmt = scwin.fn_rowInput('ipt_listAmt', i);
                cpStockCount.setReadOnly(true);
                cpStockCount.setStyle('background-color', '#f0f0f0');
                cpParval.setReadOnly(true);
                cpParval.setStyle('background-color', '#f0f0f0');
                cpListAmt.setReadOnly(true);
                cpListAmt.setStyle('background-color', '#f0f0f0');
            }
        } else {
            if (mkt === 'D') {
                $c.util.getComponent('stock_type').setValue("");
                $c.util.getComponent('stock_type_r1').setValue("");
                for (let i = 3; i < 11; i++) {
                    const cpNStockCount = scwin.fn_rowInput('ipt_nStockCount', i);
                    const cpNParval = scwin.fn_rowInput('ipt_nParval', i);
                    const cpNListAmt = scwin.fn_rowInput('ipt_nListAmt', i);
                    cpNStockCount.setReadOnly(false);
                    cpNStockCount.setStyle('background-color', '#ffffff');
                    cpNParval.setReadOnly(false);
                    cpNParval.setStyle('background-color', '#ffffff');
                    cpNListAmt.setReadOnly(false);
                    cpNListAmt.setStyle('background-color', '#ffffff');
                    scwin.fn_reset();
                }
            } else {
                for (let i = 2; i < 11; i++) {
                    const cpStockCount = scwin.fn_rowInput('ipt_stockCount', i);
                    const cpParval = scwin.fn_rowInput('ipt_parval', i);
                    const cpListAmt = scwin.fn_rowInput('ipt_listAmt', i);
                    cpStockCount.setReadOnly(false);
                    cpStockCount.setStyle('background-color', '#ffffff');
                    cpParval.setReadOnly(false);
                    cpParval.setStyle('background-color', '#ffffff');
                    cpListAmt.setReadOnly(false);
                    cpListAmt.setStyle('background-color', '#ffffff');
                }
            }
        }
    }
};


