/**
 * @method
 * @name unformat
 * @description 입력 요소 값에서 숫자·부호 이외 문자를 제거한다(코스닥 추가상장 시 소수점 허용).
 * @param {Object} obj 대상 입력 요소(DOM)
 * @returns {Boolean} 항상 true
 * @hidden N
 */
scwin.unformat = function(obj) {
    let temp = "";
    const n = String(obj.value);
    const len = n.length;
    let pos = 0;
    let ch = '';
    while (pos < len) {
        ch = n.charAt(pos);
        if ($c.util.getComponent('ipt_mkt').getValue() === '2' && $c.util.getComponent('ipt_kk').getValue() === '2') {
            if (((ch >= '0') && (ch <= '9')) || (ch === '-') || (ch === '.')) {
                temp = temp + ch;
            }
        } else {
            if (((ch >= '0') && (ch <= '9')) || (ch === '-')) {
                temp = temp + ch;
            }
        }
        pos = pos + 1;
    }
    obj.value = temp;
    return true;
};


/**
 * @method
 * @name numFormat
 * @description 입력값을 숫자 검증 후 천단위 콤마 서식으로 변환한다(범위 초과·비숫자 시 경고 후 비움).
 * @param {Object} obj 대상 입력 요소(DOM)
 * @returns {void}
 * @hidden N
 */
scwin.numFormat = async function(obj) {
    if (obj.value !== "" && !scwin.isMinusNum(obj.value)) {
        obj.value = "";
        await $c.win.alert("숫자만 입력가능합니다.");
        obj.focus();
        return;
    }
    scwin.unformat(obj);
    if (obj.value === "") {
        return;
    }
    if (isNaN(obj.value)) {
        obj.value = "";
        return;
    }
    if (Number(obj.value) > 999999999999999 || Number(obj.value) < -999999999999999) {
        obj.value = "";
        await $c.win.alert("입력한 숫자가 범위를 초과하였습니다.");
        obj.focus();
        return;
    }
    let str = Number(obj.value) + "";
    let sMinusChar = "";
    if (Number(obj.value) < 0) {
        str = str.substring(1);
        sMinusChar = "-";
    }
    let tempStr = str;
    let fltStr = "";
    if (str.indexOf(".") > -1) {
        tempStr = str.substr(0, str.indexOf("."));
        fltStr = str.substr(str.indexOf("."));
    }
    const leng = tempStr.length;
    const size = 3;
    const cnt = Math.floor(leng / size);
    const pos = leng % size;
    let result = "";
    if (cnt === 0) {
        obj.value = Number(obj.value);
        return;
    }
    for (let i = cnt; i > 0; i = i - 1) {
        result = "," + tempStr.substr(pos + (i - 1) * size, size) + result;
    }
    if (result !== '') {
        if (pos === 0) {
            obj.value = sMinusChar + result.substring(1) + fltStr;
        } else {
            obj.value = sMinusChar + str.substr(0, pos) + result + fltStr;
        }
    }
    return;
};


/**
 * @method
 * @name checkMax
 * @description 입력 길이 상한을 검사해 초과 시 경고 후 포커스를 되돌린다.
 * @param {String|Number} type 검사 유형('1' 상장주식수, '2' 종가)
 * @param {Object} obj 대상 입력 요소(DOM)
 * @returns {void}
 * @hidden N
 */
scwin.checkMax = async function(type, obj) {
    if (type === '1') {
        if (obj.value.length > 14) {
            await $c.win.alert('상장주식 수는 100억원  미만이어야 합니다.');
            obj.focus();
            return;
        }
    } else {
        if (type === '2') {
            if (obj.value.length > 7) {
                await $c.win.alert('종가는 100 만원 미만이어야 합니다.');
                obj.focus();
                return;
            }
        }
    }
};


