/**
 * @method
 * @name layer_popup
 * @description 레이어 팝업 요소를 페이드 인으로 표시하고 중앙 정렬·닫기 버튼을 바인딩한다.
 * @param {String|Object} el 레이어 요소 선택자
 * @returns {void}
 * @hidden N
 */
scwin.layer_popup = function(el) {
    const $el = $(el);
    $el.fadeIn();
    let $elWidth = ~~($el.outerWidth()),
        $elHeight = ~~($el.outerHeight()),
        docWidth = $(document).width(),
        docHeight = $(document).height();
    if ($elHeight < docHeight || $elWidth < docWidth) {
        $elHeight = 900;
        $el.css({
            marginTop: -$elHeight / 2,
            marginLeft: -$elWidth / 2
        });
    } else {
        $el.css({
            top: 0,
            left: 0
        });
    }
    $el.find('a.btn-layerClose').click(function() {
        $el.fadeOut();
        return false;
    });
};


